#include <stdarg.h>

int max_of(int count, ...)
{
    if (count <= 0)
        return 0;
    va_list args;
    va_start(args, count);
    int best = va_arg(args, int);
    for (int i = 1; i < count; i++)
    {
        int next = va_arg(args, int);
        if (next > best)
            best = next;
    }
    va_end(args);
    return best;
}

double mean_of(int count, ...)
{
    if (count <= 0)
        return 0;
    va_list args;
    va_start(args, count);
    double total = 0;
    for (int i = 0; i < count; i++)
        total += va_arg(args, double);
    va_end(args);
    return total / count;
}
